I found a way to remove this ugly box_uninit_array_into_vec_unsafe hack! And I tested it on top of your branch and checked generated MIR.
Here is my code:
#![allow(internal_features)]
#![feature(liballoc_internals)]
#![feature(super_let)]

extern crate alloc;

pub struct Foo {
    x: u128,
    y: f64,
}

macro_rules! v1 {
    [$($x:expr),+ $(,)?] => (
        ::alloc::boxed::box_uninit_array_into_vec_unsafe(
            ::alloc::intrinsics::write_box_via_move(::alloc::boxed::Box::new_uninit(), [$($x),+])
        )
    );
}

macro_rules! v2 {
    [$($x:expr),+ $(,)?] => (
        {
            super let b = ::alloc::intrinsics::write_box_via_move(::alloc::boxed::Box::new_uninit(), [$($x),+]);
            unsafe { ::alloc::boxed::box_uninit_array_into_vec_unsafe(b) }
        }
    );
}

pub fn f() -> Vec<Foo> {
    v1![Foo { x: 1, y: 2.0 }, Foo { x: 1, y: 2.0 }, Foo { x: 1, y: 2.0 }]
}
